insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort) values
  ('ARC-M01', 'Movilidad', 'Círculos de brazos', 'Hombro', 'Peso corporal', 'De pie con los brazos estirados a los lados, haces círculos hacia delante y luego hacia atrás, de pequeños a grandes.', '10 hacia delante y 10 hacia atrás. Hombros lejos de las orejas.', '', '', '', 80), 
  ('ARC-M02', 'Movilidad', 'Movilidad de hombro con palo', 'Hombro', 'Palo o banda', 'Con un palo agarrado muy abierto y los brazos estirados, lo pasas por encima de la cabeza hasta detrás y vuelves.', 'Si no pasa sin doblar los codos, abre más el agarre. 10 repeticiones lentas.', '', '', '', 81), 
  ('ARC-M03', 'Movilidad', 'Rodilla al pecho de pie', 'Glúteo y cadera', 'Peso corporal', 'De pie, subes una rodilla y la abrazas contra el pecho un segundo; bajas y cambias de pierna, caminando o en el sitio.', 'Ponte de puntillas con la pierna de apoyo para ganar equilibrio. 8 por pierna.', '', '', '', 82), 
  ('ARC-M04', 'Movilidad', 'Balanceo de pierna adelante y atrás', 'Cadera y femoral', 'Peso corporal', 'Apoyada en una pared o máquina, balanceas una pierna estirada hacia delante y hacia atrás, cada vez un poco más alto.', 'El tronco quieto: se mueve la pierna, no la espalda. 10-12 por pierna.', '', '', '', 83), 
  ('ARC-M05', 'Movilidad', 'Balanceo de pierna lateral', 'Aductores y glúteo medio', 'Peso corporal', 'De frente a una pared y apoyada con las manos, balanceas una pierna de lado a lado por delante del cuerpo.', 'Abre un poco más en cada balanceo, sin forzar. 10-12 por pierna.', '', '', '', 84), 
  ('ARC-M06', 'Movilidad', 'Zancada de corredor', 'Flexor de cadera', 'Peso corporal', 'En zancada larga con las manos en el suelo a los lados del pie de delante, llevas la cadera hacia delante y hacia atrás.', 'La rodilla de atrás puede ir apoyada. 8 balanceos por lado, sin rebotes.', '', '', '', 85), 
  ('ARC-M07', 'Movilidad', 'World''s greatest stretch', 'Cadera, espalda alta y hombro', 'Peso corporal', 'Desde la zancada de corredor, apoyas la mano contraria en el suelo y abres el otro brazo hacia el techo girando el pecho.', 'Sigue la mano con la mirada. 5 por lado. Calienta casi todo el cuerpo en un solo ejercicio.', '', '', '', 86), 
  ('ARC-M08', 'Movilidad', 'Cadera 90/90', 'Cadera', 'Suelo', 'Sentada en el suelo con las dos rodillas dobladas a 90 grados, giras las piernas de un lado a otro.', 'Pecho alto y sin usar las manos si puedes. 6-8 cambios lentos.', '', '', '', 87), 
  ('ARC-M09', 'Movilidad', 'Plancha con rotación', 'Abdomen y hombro', 'Peso corporal', 'En plancha sobre los codos, giras el cuerpo hacia un lado hasta quedar en plancha lateral y vuelves al centro.', 'Cadera alta, sin hundirla al girar. 5 por lado, controlado.', '', '', '', 88)
